#nullable enable // autogenerated

using MVZ2.GameContent.Effects;      // GridFire
using MVZ2.Vanilla.Audios;           // VanillaSoundID
using MVZ2.Vanilla.Contraptions;     // AIEntityBehaviour  ← 补上
using MVZ2.Vanilla.Entities;         // PlaySound / GetGrid / GetSpawnParams  ← 补上
using MVZ2.Vanilla.Properties;       // VanillaEntityPropertyMeta
using PVZEngine.Definitions;
using PVZEngine.Entities;
using PVZEngine.Tools.Timing;        // FrameTimer
using MVZ2.GameContent.Entities;
using MVZ2.Vanilla.Pickups;
using MVZ2.Vanilla.StateMachine;
using MVZ2Logic.Entities;
using PVZEngine.Modifiers;
using PVZEngine.Tools;
using UnityEngine;

namespace MVZ2.GameContent.Contraptions
{
    [AutoEntityBehaviourDefinition(VanillaContraptionNames.flintAndSteel)]
    public class FlintAndSteel : AIEntityBehaviour
    {
        public FlintAndSteel(string nsp, string name) : base(nsp, name)
        {
        }

public override void Init(Entity entity)
{
    base.Init(entity);

    var pos = entity.Position;
    pos.y += SPAWN_HEIGHT;
    entity.Position = pos;

    entity.SetProperty(PROP_TIMER, new FrameTimer(TRIGGER_FRAMES));
}

protected override void UpdateAI(Entity entity)
{
    base.UpdateAI(entity);

    var timer = entity.GetProperty<FrameTimer>(PROP_TIMER);
    if (timer == null) return;

    timer.Run();
    if (!timer.Expired) return;

    entity.PlaySound(VanillaSoundID.fireIgnite);

    var grid = entity.GetGrid();
    if (grid != null)
    {
        var param = entity.GetSpawnParams();
        GridFire.Spawn(grid, entity, param);
    }

    entity.Remove();
}

public const float SPAWN_HEIGHT  = 64f;   // 抬多高
public const int   TRIGGER_FRAMES = 22;   // 大约多少帧后落地
        public static readonly VanillaEntityPropertyMeta<FrameTimer> PROP_TIMER =
            new VanillaEntityPropertyMeta<FrameTimer>("timer");
    }
}